      const pm = day.querySelector('.ml-pause'); if (pm) { pm.setAttribute('aria-pressed', String(paused)); pm.textContent = (D.reduced ? 'Reduced' : paused ? 'Play' : 'Pause') + ' motion'; if (D.reduced) pm.disabled = true; }
